import 'package:http/http.dart' as http;
import 'package:html/parser.dart' as html_parser;
import 'package:intl/intl.dart';
import '../models/anime_release.dart';

class CrunchyrollService {
  static const String calendarUrl = 'https://www.crunchyroll.com/de/simulcastcalendar?filter=premium';
  
  Future<List<AnimeRelease>> getReleasesForWeek(DateTime startDate) async {
    try {
      return await _scrapeCalendar();
    } catch (e) {
      print('Error loading releases: $e');
      return [];
    }
  }

  Future<List<AnimeRelease>> getReleasesForDay(DateTime date) async {
    final weekData = await getReleasesForWeek(date);
    final weekday = date.weekday; // 1 = Monday, 7 = Sunday
    
    return weekData.where((release) {
      return release.releaseTime.weekday == weekday;
    }).toList();
  }

  Future<List<AnimeRelease>> _scrapeCalendar() async {
    final List<AnimeRelease> allReleases = [];
    
    try {
      print('Scraping Crunchyroll calendar: $calendarUrl');
      
      final response = await http.get(
        Uri.parse(calendarUrl),
        headers: {
          'User-Agent': 'MeineApp/1.0',
        },
      );

      if (response.statusCode == 200) {
        print('Successfully loaded calendar page');
        final document = html_parser.parse(response.body);
        
        // Die Tage sind in .day Elementen, wir verwenden nth-child Selektoren
        // Montag = .day:first-child
        // Dienstag = .day:nth-child(3)
        // Mittwoch = .day:nth-child(5)
        // Donnerstag = .day:nth-child(7)
        // Freitag = .day:nth-child(9)
        // Samstag = .day:nth-child(11)
        // Sonntag = .day:nth-child(13)
        
        final now = DateTime.now();
        final weekStart = now.subtract(Duration(days: now.weekday - 1)); // Montag dieser Woche
        
        final daySelectors = [
          ('.day:first-child', 0),      // Montag
          ('.day:nth-child(3)', 1),     // Dienstag
          ('.day:nth-child(5)', 2),     // Mittwoch
          ('.day:nth-child(7)', 3),     // Donnerstag
          ('.day:nth-child(9)', 4),     // Freitag
          ('.day:nth-child(11)', 5),    // Samstag
          ('.day:nth-child(13)', 6),    // Sonntag
        ];
        
        for (var selectorInfo in daySelectors) {
          final selector = selectorInfo.$1;
          final dayOffset = selectorInfo.$2;
          final dayDate = weekStart.add(Duration(days: dayOffset));
          
          final dayElements = document.querySelectorAll(selector);
          
          for (var dayElement in dayElements) {
            // Anime Titel extrahieren
            final seasonNames = dayElement.querySelectorAll('.season-name');
            
            for (var seasonElement in seasonNames) {
              try {
                // Anime Name
                final nameElement = seasonElement.querySelector('[itemprop="name"]');
                if (nameElement == null) continue;
                final animeName = nameElement.text.trim();
                
                // Anime Link
                final linkElement = seasonElement.querySelector('a');
                final animeLink = linkElement?.attributes['href'] ?? '';
                
                // Episode Info (aus .availability)
                final availabilityElement = seasonElement.parent?.querySelector('.availability');
                var episodeInfo = '';
                var episodeNumber = '1';
                
                if (availabilityElement != null) {
                  final linkElements = availabilityElement.querySelectorAll('a');
                  for (var link in linkElements) {
                    episodeInfo = link.text.trim().replaceAll('\n', '').replaceAll('Verfügbar', '').trim();
                    break;
                  }
                  
                  // Extrahiere Episode-Nummer
                  final episodeMatch = RegExp(r'[Ee]pisode?\s*(\d+)|[Ff]olge\s*(\d+)|[Ss]\d+[Ee](\d+)|\b(\d+)\b').firstMatch(episodeInfo);
                  if (episodeMatch != null) {
                    episodeNumber = episodeMatch.group(1) ?? episodeMatch.group(2) ?? episodeMatch.group(3) ?? episodeMatch.group(4) ?? '1';
                  }
                }
                
                // Uhrzeit extrahieren (falls vorhanden)
                var releaseTime = dayDate;
                final timeElements = seasonElement.parent?.querySelectorAll('.availability-time');
                if (timeElements != null && timeElements.isNotEmpty) {
                  final timeText = timeElements.first.text.trim();
                  final timeMatch = RegExp(r'(\d{1,2}):(\d{2})').firstMatch(timeText);
                  if (timeMatch != null) {
                    final hour = int.parse(timeMatch.group(1)!);
                    final minute = int.parse(timeMatch.group(2)!);
                    releaseTime = DateTime(dayDate.year, dayDate.month, dayDate.day, hour, minute);
                  }
                }
                
                // Bild von AniDB generieren (basierend auf Anime-Name)
                final imageUrl = _getAniDbImage(animeName);
                
                allReleases.add(AnimeRelease(
                  title: animeName,
                  episodeNumber: episodeNumber,
                  episodeTitle: episodeInfo,
                  releaseTime: releaseTime,
                  imageUrl: imageUrl,
                  seriesUrl: animeLink.startsWith('http') ? animeLink : 'https://www.crunchyroll.com$animeLink',
                  episodeUrl: animeLink.startsWith('http') ? animeLink : 'https://www.crunchyroll.com$animeLink',
                  isPremiere: episodeNumber == '1',
                ));
                
              } catch (e) {
                print('Error parsing anime: $e');
                continue;
              }
            }
          }
        }
        
        print('Found ${allReleases.length} anime releases');
      } else {
        print('HTTP Error: ${response.statusCode}');
      }
    } catch (e) {
      print('Error scraping calendar: $e');
    }
    
    return allReleases;
  }
  
  String _getAniDbImage(String animeName) {
    // Fallback zu MyAnimeList CDN mit generischem Bild
    // In der Zukunft könnte hier eine AniDB API-Abfrage implementiert werden
    return 'https://cdn.myanimelist.net/images/anime/1171/109222l.jpg';
  }
}
